/* AiBugReportMapper.insertBugReport */
INSERT INTO ai_bug_report (
    conversation_id, message_id, error_type, severity, description,
    screenshot_url, status, reported_by, reported_at
) VALUES (
    #{conversationId}, #{messageId}, #{errorType}, #{severity}, #{description},
    #{screenshotUrl}, #{status}, #{reportedBy}, #{reportedAt}
)

mapper.select:
/* AiBugReportMapper.selectBugReportById */
SELECT id, conversation_id, message_id, error_type, severity, description,
       screenshot_url, status, reported_by, reported_at,
       resolved_by, resolved_at, resolution_note
FROM ai_bug_report
WHERE id = #{id}

/* AiBugReportMapper.selectBugReportList */ SELECT br.id, br.conversation_id, br.message_id, br.error_type, br.severity, br.description, br.screenshot_url, br.status, br.reported_by, br.reported_at, br.resolved_by, br.resolved_at, br.resolution_note, c.title AS conversation_title, m.content AS message_content, m.role AS message_role, reporter.email AS reporter_email FROM ai_bug_report br INNER JOIN ai_conversation c ON c.id = br.conversation_id LEFT JOIN ai_message m ON m.id = br.message_id INNER JOIN `user` reporter ON reporter.user_no = br.reported_by
AND br.status = #{status}
AND br.error_type = #{errorType}
AND br.severity = #{severity}
ORDER BY br.reported_at DESC, br.id DESC LIMIT #{limit} OFFSET #{offset}

/* AiBugReportMapper.countBugReports */
SELECT COUNT(1)
FROM ai_bug_report br


        AND br.status = #{status}


        AND br.error_type = #{errorType}


        AND br.severity = #{severity}
